using Ariadne.NET.Analysis;
using FluentAssertions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace Ariadne.NET.Tests.Analysis;

public class RazorSourceTests
{
    private const string GeneratedPath = "/obj/gen/Counter_razor.g.cs";

    private const string Mapped = """
        // <auto-generated/>
        namespace App
        {
            #line hidden
            public partial class Counter
            {
                void Render()
                {
        #line (6,44)-(6,74) 24 "/app/Components/Counter.razor"
        System.Console.WriteLine(_count
        #line default
        #line hidden
                    );
                }

                int _count;
            }
        }
        """;

    [Fact]
    public void MappedSpan_ReportsTheRazorFileAndLine()
    {
        var tree = Parse(Mapped);
        var span = tree.GetRoot().DescendantNodes().OfType<IdentifierNameSyntax>().First(n => string.Equals(n.Identifier.Text, "_count", StringComparison.Ordinal)).Span;

        var location = RazorSource.Locate(tree, span, FileOf(tree), CancellationToken.None);

        location.FilePath.Should().Be("/app/Components/Counter.razor");
        location.Line.Should().Be(6);
    }

    // Every component tree starts with the usings of _Imports.razor, mapped to that file, so the first #line names the wrong file.
    [Fact]
    public void HiddenSpan_ReportsLine1OfThePragmaFile_NotTheImportsFile()
    {
        var tree = Parse(WithImports);

        var location = RazorSource.Locate(tree, ClassIdentifier(tree), FileOf(tree), CancellationToken.None);

        location.Should().Be(new SourceLocation("/app/Components/Counter.razor", 1, 1));
    }

    [Fact]
    public void DeclarationTree_TakesTheFileOfItsSibling()
    {
        var main = Parse(WithImports);
        var declarations = CSharpSyntaxTree.ParseText(Declarations, path: "/obj/gen/Counter_razor.decl.g.cs");

        var files = RazorSource.FilePaths(new HashSet<SyntaxTree> { main, declarations }, CancellationToken.None);

        files[main].Should().Be("/app/Components/Counter.razor");
        files[declarations].Should().Be("/app/Components/Counter.razor");
        RazorSource.Locate(declarations, ClassIdentifier(declarations), files[declarations], CancellationToken.None)
            .Should().Be(new SourceLocation("/app/Components/Counter.razor", 1, 1));
    }

    [Fact]
    public void NoPragmaNoSibling_UsesTheTreesOwnPath()
    {
        var declarations = CSharpSyntaxTree.ParseText(Declarations, path: "/obj/gen/Counter_razor.decl.g.cs");

        var files = RazorSource.FilePaths(new HashSet<SyntaxTree> { declarations }, CancellationToken.None);

        files[declarations].Should().Be("/obj/gen/Counter_razor.decl.g.cs");
        RazorSource.Locate(declarations, ClassIdentifier(declarations), files[declarations], CancellationToken.None)
            .Should().Be(new SourceLocation("/obj/gen/Counter_razor.decl.g.cs", 7, 26));
    }

    private const string WithImports = """
        #pragma checksum "/app/Components/Counter.razor" "{8829d00f-11b8-4213-878b-770e8597ac16}" "ab"
        // <auto-generated/>
        namespace App
        {
        #line (1,2)-(1,26) "/app/_Imports.razor"
        using System.Globalization;
        #line default
        #line hidden
            public partial class Counter { }
        }
        """;

    private const string Declarations = """
        // <auto-generated/>
        namespace App
        {
        #line (1,2)-(1,26) "/app/_Imports.razor"
        using System.Globalization;
        #line hidden
            public partial class Counter { }
        }
        """;

    private static string FileOf(SyntaxTree tree) => RazorSource.FilePaths(new HashSet<SyntaxTree> { tree }, CancellationToken.None)[tree];

    private static SyntaxTree Parse(string text) => CSharpSyntaxTree.ParseText(text, path: GeneratedPath);

    private static Microsoft.CodeAnalysis.Text.TextSpan ClassIdentifier(SyntaxTree tree) =>
        tree.GetRoot().DescendantNodes().OfType<ClassDeclarationSyntax>().First().Identifier.Span;
}
